    var started=Date.now(), selected='500G', form=document.getElementById('form'),cart=[];
    function normalizeMoroccanMobile(value) {
  const compact = String(value ?? '').trim().replace(/[٠-٩]/g, digit => String(digit.charCodeAt(0) - 1632)).replace(/[۰-۹]/g, digit => String(digit.charCodeAt(0) - 1776)).replace(/[\s()-]/g, '');
  const match = /^(?:0|(?:\+|00)?212)([67]\d{8})$/.exec(compact);
  return match ? '0' + match[1] : '';
}
    var phoneInput=document.getElementById('phone'),phoneError=document.getElementById('phoneError'),phoneMessage='المرجو إدخال رقم هاتف صحيح وشغّال باش نتاصلو بيك لتأكيد الطلب.';
