    function refreshOffers(){offerSelect.innerHTML='';Object.keys(offers).filter(function(k){return offers[k].product===productSelect.value}).forEach(function(k){var option=document.createElement('option');option.value=k;option.textContent=offers[k].name+' — '+offers[k].price+' درهم';offerSelect.append(option)})}
    productSelect.onchange=refreshOffers;refreshOffers();renderCart();
    function choose(key,count,increment){if(hasPending()){showDetails();return}if(!offers[key])return;selected=key;productSelect.value=offers[key].product;refreshOffers();offerSelect.value=key;var old=cart.find(function(i){return i.offer_package===key});if(old){if(increment)old.count=Math.min(20,old.count+(count||1))}else cart.push({offer_package:key,count:count||1});renderCart();funnel('select_item')}
    document.getElementById('addItem').onclick=function(){choose(offerSelect.value,Math.min(20,Math.max(1,Math.floor(Number(document.getElementById('itemCount').value)||1))),true);queueCartSave()};
